<?php require 'includes/db.php'; $title='Employees';
if(isset($_GET['delete'])){$s=$conn->prepare("DELETE FROM employees WHERE id=?");$s->bind_param('i',$_GET['delete']);$s->execute();header('Location: employees.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){$s=$conn->prepare("INSERT INTO employees(name,email,phone,department_id,designation,joining_date,status) VALUES(?,?,?,?,?,?,?)");$s->bind_param('sssisss',$_POST['name'],$_POST['email'],$_POST['phone'],$_POST['department_id'],$_POST['designation'],$_POST['joining_date'],$_POST['status']);$s->execute();header('Location: employees.php');exit;}
$deps=$conn->query("SELECT * FROM departments ORDER BY name");$rows=$conn->query("SELECT e.*,d.name department FROM employees e LEFT JOIN departments d ON d.id=e.department_id ORDER BY e.id DESC");require 'includes/header.php';?>
<div class="toolbar"><div><h2>Employee Directory</h2><p>Manage company staff in RDS MySQL.</p></div><button class="btn" onclick="add.showModal()">+ Add Employee</button></div>
<section class="panel"><table><tr><th>Name</th><th>Department</th><th>Designation</th><th>Email</th><th>Status</th><th>Action</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><b><?=htmlspecialchars($r['name'])?></b><br><small><?=htmlspecialchars($r['phone']??'')?></small></td><td><?=htmlspecialchars($r['department']??'—')?></td><td><?=htmlspecialchars($r['designation'])?></td><td><?=htmlspecialchars($r['email'])?></td><td><em><?=htmlspecialchars($r['status'])?></em></td><td><a class="danger" href="?delete=<?=$r['id']?>" onclick="return confirm('Delete employee?')">Delete</a></td></tr><?php endwhile;?></table></section>
<dialog id="add"><form method="post"><h3>Add Employee <button type="button" onclick="add.close()">×</button></h3><div class="grid"><label>Name<input name="name" required></label><label>Email<input name="email" type="email" required></label><label>Phone<input name="phone"></label><label>Department<select name="department_id"><?php while($d=$deps->fetch_assoc()):?><option value="<?=$d['id']?>"><?=htmlspecialchars($d['name'])?></option><?php endwhile;?></select></label><label>Designation<input name="designation" required></label><label>Joining Date<input name="joining_date" type="date" required></label><label>Status<select name="status"><option>Active</option><option>Inactive</option></select></label></div><button class="btn">Save Employee</button></form></dialog><?php require 'includes/footer.php';?>